import json
from copy import deepcopy
from codec import parse_event, read_json, string, integer


def _validate_seen_event_quantities(event):
    """Reject bool/float quantities inside a canonical seen event.

    Booleans are a subclass of int, so codec.integer alone would accept them;
    floats fail isinstance(x, int) but are validated here for completeness.
    """
    op = event.get('op')
    if op == 'restock':
        if isinstance(event['qty'], bool):
            raise ValueError('boolean quantity')
    elif op == 'reserve':
        for pair in event['lines']:
            if isinstance(pair, (list, tuple)) and len(pair) == 2:
                sku, qty = pair
                if not string(sku) or isinstance(qty, bool) or not integer(qty, 1):
                    raise ValueError('reserve line quantity')
            else:
                raise ValueError('reserve line shape')


def validate(state):
    if not isinstance(state, dict) or set(state) != {'stock', 'requests', 'seen'}:
        raise ValueError('state fields')
    if not all(isinstance(state[key], dict) for key in state):
        raise ValueError('state mappings')
    for sku, qty in state['stock'].items():
        if not string(sku) or isinstance(qty, bool) or not integer(qty, 0):
            raise ValueError('stock')
    for request, lines in state['requests'].items():
        if not string(request) or not isinstance(lines, dict):
            raise ValueError('requests')
        for sku, qty in lines.items():
            if not string(sku) or isinstance(qty, bool) or not integer(qty, 1):
                raise ValueError('request quantity')
    for event_id, event in state['seen'].items():
        if not string(event_id) or not isinstance(event, dict):
            raise ValueError('seen')
        if event.get('id') != event_id:
            raise ValueError('seen id mismatch')
        try:
            canonical = parse_event(json.dumps(event, ensure_ascii=False))
        except (TypeError, ValueError) as exc:
            raise ValueError('seen event') from exc
        if canonical != event:
            raise ValueError('noncanonical seen event')
        _validate_seen_event_quantities(event)
    return state


def dump_state(state):
    validate(state)
    state = deepcopy(state)
    return json.dumps({'version': 1, 'state': state}, ensure_ascii=False,
                      sort_keys=True, separators=(',', ':')) + '\n'


def load_state(text):
    wrapper = read_json(text)
    if not isinstance(wrapper, dict) or set(wrapper) != {'version', 'state'}:
        raise ValueError('wrapper')
    if type(wrapper['version']) is not int or wrapper['version'] != 1:
        raise ValueError('version')
    return deepcopy(validate(wrapper['state']))

